{
  "implementation": "def solve(case):
    nodes = case['nodes']
    required_symbols = set(case['required_symbols'])
    symbol_nodes = {}
    for n in nodes:
        symbol_nodes.setdefault(n['symbol'], []).append(n)
    keep_removable = set()
    for sym in required_symbols:
        sym_list = symbol_nodes.get(sym, [])
        non_rem = [n for n in sym_list if not n['removable']]
        rem = [n for n in sym_list if n['removable']]
        if not non_rem and rem:
            best = max(rem, key=lambda x: x['utility'])
            keep_removable.add(best['id'])
    retained = set()
    removed = set()
    for n in nodes:
        if not n['removable']:
            retained.add(n['id'])
        elif n['id'] in keep_removable:
            retained.add(n['id'])
        else:
            removed.add(n['id'])
    return {
        'removed_node_ids': list(removed),
        'retained_node_ids': list(retained)
    }"
}
